// Triage Classifier: Categorize applicant into VIP, Duplicate, or Standard
const res = $input.first().json;

const isDuplicate = Boolean(res.is_duplicate || res.duplicate_detected);
const rec = res.record || res;
const fitScore = typeof rec.fit_score === 'number' ? rec.fit_score : (typeof res.fit_score === 'number' ? res.fit_score : 0);

let category = 'standard';
if (isDuplicate) {
  category = 'duplicate';
} else if (fitScore >= 85) {
  category = 'vip';
}

return {
  json: {
    category,
    is_duplicate: isDuplicate,
    fit_score: fitScore,
    record: rec,
    raw_response: res
  }
};

