// Build Slack Block-Kit Card for VIP Applicant (>85)
const triage = $('Code: Triage Classifier').first().json;
const rec = triage.record;
const fitScore = triage.fit_score;
const memberId = rec.id || 'new';
const tags = (rec.sector_tags || []).map(t => `#${t}`).join(' ') || '#tech';
const consoleUrl = 'https://offline-os-gray.vercel.app';

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: '🌟 VIP APPLICANT DETECTED (>85/100)',
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Name:*\n${rec.name}` },
      { type: 'mrkdwn', text: `*Company:*\n${rec.company || 'Stealth'}` },
      { type: 'mrkdwn', text: `*Role:*\n${rec.role_title || 'Founder'}` },
      { type: 'mrkdwn', text: `*Fit Score:*\n🎯 *${fitScore}/100*` }
    ]
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Sector Tags:* ${tags}\n*AI Evaluation Thesis:*\n> _"${rec.fit_score_reasoning || 'High potential founder with strong domain authority.'}"_`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Bio & Operator Notes:*\n${rec.bio_notes || 'No bio provided.'}`
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'actions',
    block_id: 'vip_intake_actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '🟢 Approve & Welcome', emoji: true },
        style: 'primary',
        action_id: 'approve_welcome',
        value: String(memberId),
        url: `${consoleUrl}?tab=people&id=${memberId}`
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '🤝 Suggest Intro', emoji: true },
        action_id: 'suggest_intro',
        value: String(memberId),
        url: `${consoleUrl}?tab=intros&memberId=${memberId}`
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: '🔬 Deep Research Memo', emoji: true },
        action_id: 'view_research',
        value: String(memberId),
        url: `${consoleUrl}?tab=intelligence&query=${encodeURIComponent(rec.name)}`
      }
    ]
  }
];

return {
  json: {
    channel: '#offline-vip-intake',
    text: `🌟 VIP Applicant: ${rec.name} (${rec.role_title} @ ${rec.company}) | Score: ${fitScore}/100`,
    blocks: blocks
  }
};

// Build Slack Block-Kit Card for Duplicate Applicant
const triage = $('Code: Triage Classifier').first().json;
const res = triage.raw_response;
const consoleUrl = 'https://offline-os-gray.vercel.app';
const conf = Math.round((res.confidence || 0.95) * 100);

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: '⚠️ DUPLICATE APPLICANT DETECTED',
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Applicant Name:*\n${res.name || 'Unknown'}` },
      { type: 'mrkdwn', text: `*Duplicate Of:*\nRecord #${res.duplicate_of || 'Canonical'}` },
      { type: 'mrkdwn', text: `*Match Confidence:*\n🚨 *${conf}% Match*` },
      { type: 'mrkdwn', text: `*Resolution Status:*\nPending Operator Review` }
    ]
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*AI Deduplication Reasoning:*\n> _"${res.reasoning || 'Fuzzy matching flagged strong similarity with existing canonical record.'}"_`
    }
  },
  {
    type: 'actions',
    block_id: 'duplicate_actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '⚠️ Review in Duplicates Queue', emoji: true },
        style: 'danger',
        action_id: 'review_duplicate',
        url: `${consoleUrl}?tab=duplicates`
      }
    ]
  }
];

return {
  json: {
    channel: '#offline-duplicates',
    text: `⚠️ Duplicate Flagged: ${res.name} matched Record #${res.duplicate_of} (${conf}%)`,
    blocks: blocks
  }
};

// Standard Member Notification
const triage = $('Code: Triage Classifier').first().json;
const rec = triage.record;
const fitScore = triage.fit_score;

return {
  json: {
    channel: '#offline-intake',
    text: `✨ New Member Ingested: ${rec.name} (${rec.role_title || 'Member'} @ ${rec.company || 'Independent'}) | Score: ${fitScore}/100`
  }
};
